import { useNavigate } from "react-router-dom";
import { useResults } from "../context/ResultsContext";

export default function Dashboard() {
  const navigate = useNavigate();
  const { results } = useResults();

  const total = results.length;
  const shortlisted = results.filter(
    (r) => r.decision === "Shortlisted",
  ).length;
  const rejected = results.filter((r) => r.decision === "Rejected").length;
  const reviewLater = results.filter(
    (r) => r.decision === "Review Later",
  ).length;

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2 className="page-title">Dashboard</h2>

        <div className="theme-card mb-4 text-center">
          <p>Start by adding a Job Description, then upload resumes.</p>
          <button className="theme-btn mt-3" onClick={() => navigate("/jobs")}>
            Add Job Description →
          </button>
        </div>

        <div className="theme-card">
          <h4>Latest Screening Results</h4>
          <div className="d-flex gap-4 mt-3">
            <div>Total: {total}</div>
            <div>Shortlisted: {shortlisted}</div>
            <div>Rejected: {rejected}</div>
            <div>Review Later: {reviewLater}</div>
          </div>
          <button
            className="theme-btn mt-3"
            onClick={() => navigate("/results")}
          >
            View Results →
          </button>
        </div>
      </div>
    </div>
  );
}
